<script setup lang="ts">import{onMounted,ref,watch}from'vue';import{api}from'../api';import type{Post}from'../types';const items=ref<Post[]>([]),status=ref(''),q=ref('');async function load(){items.value=await api('/admin/posts?status='+status.value+'&q='+encodeURIComponent(q.value))}watch(status,load);onMounted(load);async function remove(p:Post){if(!confirm(`确定删除《${p.title}》？此操作无法撤销。`))return;await api('/admin/posts/'+p.id,{method:'DELETE'});load()}</script><template><div class="admin-title"><div><p class="eyebrow">CONTENT</p><h1>文章管理</h1></div><RouterLink class="button" to="/admin/posts/new">+ 新建文章</RouterLink></div><div class="filters"><input v-model="q" @keyup.enter="load" placeholder="搜索标题"><select v-model="status"><option value="">全部状态</option><option value="published">已发布</option><option value="draft">草稿</option></select><button @click="load">筛选</button></div><div class="panel table-wrap"><table><thead><tr><th>标题</th><th>分类</th><th>状态</th><th>更新</th><th>操作</th></tr></thead><tbody><tr v-for="p in items" :key="p.id"><td><b>{{p.title}}</b><small>/{{p.slug}}</small></td><td>{{p.category}}</td><td><span class="badge">{{p.status==='published'?'已发布':'草稿'}}</span></td><td>{{p.updatedAt.slice(0,10)}}</td><td><RouterLink :to="`/admin/posts/${p.id}`">编辑</RouterLink> · <button class="link danger" @click="remove(p)">删除</button></td></tr></tbody></table></div></template>
